// The collection operations of the unsigned arrays.
fun main() {
    val u = uintArrayOf(3u, 4000000000u, 7u, 1u)
    u.forEach { print("$it ") }
    println()
    println(u.reversed())
    println(u.sorted())
    println(u.sortedDescending())
    println(u.sum())
    println(u.max())
    println(u.min())
    println(u.joinToString("|"))
    println(u.map { it + 1u })
    println(u.filter { it > 5u })
    println(u.indexOf(7u))
    println(u.contains(4000000000u))
    println(u.first())
    println(u.last { it < 5u })
    println(u.copyOf(6).contentToString())
    println(u.copyOfRange(1, 3).contentToString())
    println(u.reversedArray().contentToString())
    println(u.toList())
    println(u.take(2))
    println(u.drop(3))
    println(u.fold(0u) { a, b -> a + b })
    println(u.reduce { a, b -> maxOf(a, b) })
    println(u.zip(listOf("a", "b")))
    println(u.asSequence().filter { it % 2u == 1u }.toList())
    println(u.any { it > 3000000000u })
    println(u.count { it < 5u })
    println(u.withIndex().map { it.index.toUInt() * it.value }.toList())
    val (a, b) = u
    println("$a $b")
    u.sort()
    println(u.contentToString())
    u.sortDescending()
    println(u.contentToString())
    u.fill(9u, 1, 3)
    println(u.contentToString())
    println((u + 5u).contentToString())
    println(u.contentEquals(uintArrayOf(4000000000u, 9u, 9u, 1u)))
    println(u.toTypedArray().size)
    println(intArrayOf(-1, 2).toUIntArray().contentToString())
    println(uintArrayOf(5u).toIntArray().contentToString())
    println(uintArrayOf(1u, 2u).copyInto(UIntArray(3), 1).contentToString())

    val b8 = ubyteArrayOf(200u, 100u, 255u)
    println(b8.sorted())
    println(b8.sum())
    println(b8.max())
    println(b8.map { it.toInt() })
    println(b8.reversed())
    println(b8.joinToString())
    println(b8.copyOf().also { it.sort() }.contentToString())
    println(byteArrayOf(-1, 3).toUByteArray().contentToString())
    println(b8.toByteArray().contentToString())

    val s16 = ushortArrayOf(60000u, 5u)
    println(s16.sorted())
    println(s16.sum())
    println(s16.reversed())
    println(s16.asSequence().toList())

    val l = ulongArrayOf(18446744073709551615u, 5u, 9223372036854775808u)
    println(l.sorted())
    println(l.sum())
    println(l.max())
    println(l.reversed())
    println(l.joinToString())
    println(l.sortedDescending())
    println(l.binarySearch(5u))

    println(listOf(1u, 2u, 3u).sum())
    println(listOf(1uL, 2uL).sum())
    println(sequenceOf<UByte>(200u, 100u).sum())
    println(arrayOf(1u, 2u).sum())
    println(listOf<UShort>(65535u, 1u).sum())
    println(intArrayOf(5, 6).toUIntArray().sum())
    println(UIntArray(3) { it.toUInt() }.contentToString())
    println(uintArrayOf().firstOrNull())
}
